css:
/* INES — SWISS POSTER, v6 (theme author guide v1.5).
   One sheet of paper (day: #F3F2EE, night: #0E0E0E), one ink, one red (#E10600).
   One family (Inter, bundled as "Ines Grotesk" / "Ines Display"). Radius 0. No shadows.
   Rules: 1px hairline to divide, 3px ink rule to open a section. 8px spacing grid.
   Signature: a red sun sinking behind a black ground band on Home. Nowhere else. */

:root{
  --mari-tokens-version:1;
  --mari-toast-font-size:0.9375rem;
  --mari-home-shortcut-size:0.9375rem;
  --mari-home-shortcut-desc-size:0.875rem;
  --mari-min-ui-text:12px;
  --ines-red:#e10600;
  --ines-font:"Ines Grotesk","Inter","Helvetica Neue",Helvetica,Arial,sans-serif;
  --ines-display:"Ines Display","Ines Grotesk","Inter","Helvetica Neue",Helvetica,Arial,sans-serif;
  --radius:0px;
  --mari-font-ui:var(--ines-font);
  --mari-font-heading:var(--ines-display);
  --mari-font-chat:var(--ines-font);
  --ov-serif:var(--ines-display);
  --mari-chat-font-size:16px;
  --mari-text-outline:0;
  --mari-selected-tint:var(--foreground);
  --mari-art-saturation-1:0%; --mari-art-saturation-2:0%;
  --mari-focus-ring-color:var(--foreground);
  --marinara-theme-accent-pulse:none;
  --glow-primary:transparent; --glow-accent:transparent;
  --mari-top-bar-plate:transparent;
  --mari-top-bar-plate-radius:0;
  --mari-home-art:none;
  --mari-home-wash:transparent;
  --mari-home-widget-radius:0;
  --mari-home-widget-border-width:1px;
  --mari-home-widget-font:var(--ines-font);
  --mari-home-widget-title-font:var(--ines-display);
  --mari-home-widget-title-size:1.5rem;
  --mari-home-widget-eyebrow-size:0.6875rem;
  --mari-home-widget-text-size:0.875rem;
  --mari-home-widget-action-size:0.875rem;
  --mari-msg-head-rule:none;
  --mari-page-veil:transparent;
  --mari-composer-placeholder:"Write.";
  /* paper everywhere: a 512px grain tile, ±3% so it never touches text contrast */
  --mari-app-backdrop-size:512px 512px;
  --mari-app-backdrop-repeat:repeat;
  --mari-app-backdrop-position:0 0;
  --mari-icon-send:url("theme:send.png");
  --ines-line:color-mix(in srgb,var(--ines-ink) 16%,transparent);
  --ines-line-strong:var(--ines-ink);
  --ines-ground:var(--ines-ink);
}

/* ── DAY ─────────────────────────────────────────── */
:root[data-theme="light"]{
  --mari-art-lightness-1:90%; --mari-art-lightness-2:86%;
  --ines-paper:#f3f2ee; --ines-ink:#111111; --ines-mute:#5c5b57; --ines-faint:#6a6863;
  --ines-sun:url("theme:sun-print.webp");
  --mari-app-backdrop:url("theme:paper-day.png");
  --mari-stage-empty-bg:#d9d6cf;
}
/* ── NIGHT ───────────────────────────────────────── */
:root,:root[data-theme="dark"]{
  --mari-art-lightness-1:14%; --mari-art-lightness-2:10%;
  --ines-paper:#0e0e0e; --ines-ink:#e9e7e1; --ines-mute:#a3a19b; --ines-faint:#8a8882;
  --ines-sun:url("theme:sun-print.webp");
  --mari-app-backdrop:url("theme:paper-night.png");
  --mari-stage-empty-bg:#161616;
  --ines-ground:#3a3936; /* by night the ground is a dark band, not the brightest thing on screen */
}
:root[data-theme="light"]{ --ines-paper:#f3f2ee; --ines-ink:#111111; --ines-mute:#5c5b57; --ines-faint:#6a6863; --ines-ground:#111111;
  --ines-sun:url("theme:sun-print.webp"); --mari-app-backdrop:url("theme:paper-day.png"); }

:root,:root[data-theme="dark"],:root[data-theme="light"]{
  --background:var(--ines-paper); --foreground:var(--ines-ink);
  --card:var(--ines-paper); --card-foreground:var(--ines-ink);
  --popover:var(--ines-paper); --popover-foreground:var(--ines-ink);
  --primary:var(--ines-red); --primary-foreground:#fff;
  --secondary:var(--ines-paper); --secondary-foreground:var(--ines-ink);
  --muted:var(--ines-paper); --muted-foreground:var(--ines-mute);
  --accent:color-mix(in srgb,var(--ines-ink) 6%,var(--ines-paper)); --accent-foreground:var(--ines-ink);
  --destructive:var(--ines-red); --destructive-foreground:#fff;
  --border:var(--ines-line); --input:var(--ines-line); --ring:var(--ines-ink);
  --sidebar:var(--ines-paper); --sidebar-foreground:var(--ines-ink); --sidebar-border:var(--ines-line);
  --sidebar-accent:transparent; --sidebar-accent-foreground:var(--ines-ink);
  --ov-line:var(--ines-line); --ov-text:var(--ines-ink); --ov-muted:var(--ines-mute); --ov-dim:var(--ines-faint);
  --ov-accent:var(--ines-red);
  --ov-hover:color-mix(in srgb,var(--ines-ink) 5%,transparent);
  --ov-active-bg:color-mix(in srgb,var(--ines-ink) 6%,var(--ines-paper));
  --mari-selected-bg:color-mix(in srgb,var(--ines-ink) 6%,var(--ines-paper));
  --ov-mode-conversation:var(--ines-ink); --ov-mode-roleplay:var(--ines-ink); --ov-mode-game:var(--ines-ink);
  --mari-mode-conversation:var(--ines-ink); --mari-mode-roleplay:var(--ines-ink); --mari-mode-game:var(--ines-ink);
  --mari-home-pink:var(--ines-ink); --mari-home-violet:var(--ines-ink);
  --mari-status-online:var(--ines-ink); --mari-status-idle:var(--ines-mute); --mari-status-dnd:var(--ines-red); --mari-status-offline:var(--ines-faint);
  --mari-gauge-ok:var(--ines-ink); --mari-gauge-warn:var(--ines-mute); --mari-gauge-danger:var(--ines-red);
  --mari-game-combat:var(--ines-ink); --mari-game-combat-text:var(--ines-paper);
  --mari-scrim:color-mix(in srgb,var(--ines-paper) 82%,transparent);
  --mari-user-avatar-placeholder:linear-gradient(var(--ines-paper),var(--ines-paper));
  --mari-dialogue-color:var(--ines-ink);
  --mari-home-widget-bg:var(--ines-paper);
  --mari-home-widget-border:var(--ines-line);
  --mari-home-widget-title-color:var(--ines-ink);
  --mari-home-widget-muted:var(--ines-mute);
  --mari-home-widget-eyebrow-color:var(--ines-mute);

  /* v1.4 contract tokens: no more internal variables */
  --mari-chrome-accent:var(--ines-ink);
  --mari-chrome-muted:var(--ines-mute);
  --mari-message-time:var(--ines-mute);
  --mari-chat-wash:none;
  --mari-chat-header-bg:var(--ines-paper);
  --mari-lore-constant:var(--ines-red); --mari-lore-selective:var(--ines-ink); --mari-lore-normal:var(--ines-faint);
  --mari-resource-accent:var(--ines-ink);
  --mari-resource-characters:var(--ines-ink); --mari-resource-personas:var(--ines-ink); --mari-resource-lorebooks:var(--ines-ink);
  --mari-resource-presets:var(--ines-ink); --mari-resource-connections:var(--ines-ink); --mari-resource-agents:var(--ines-ink);
  --mari-resource-settings:var(--ines-ink); --mari-resource-backgrounds:var(--ines-ink); --mari-resource-browser:var(--ines-ink);
  --mari-ctrlk-conversation:var(--ines-ink); --mari-ctrlk-roleplay:var(--ines-ink); --mari-ctrlk-game:var(--ines-ink);
  --mari-game-combat-bg:var(--ines-ink); --mari-game-combat-bg-hover:var(--ines-red); --mari-game-combat-border:var(--ines-ink);
  --mari-top-bar-plate-active:transparent;
  --mari-home-widget-glow:none;
  /* top bar: the paper, one hairline under it */
  --mari-top-bar-bg:var(--ines-paper);
}

/* ── GLOBAL: flat, square, still ─────────────────── */
*,*::before,*::after{border-radius:0!important;box-shadow:none!important;text-shadow:none!important;
  backdrop-filter:none!important;-webkit-backdrop-filter:none!important;}
*,*::before,*::after{animation-duration:0s!important;transition:none!important;}
.stagger-children > *{opacity:1!important;}
html,body,button,input,select,textarea{font-family:var(--ines-font)!important;}
body{-webkit-font-smoothing:antialiased;font-feature-settings:"cv11","ss01";}
[class*="bg-gradient"],[class*="bg-linear"],[class*="bg-radial"],[class*="bg-[linear"],[class*="bg-[radial"]{background-image:none!important;}
.mari-sidebar-header .h-6.w-6{background:var(--ines-ink)!important;color:var(--ines-paper)!important;}
[class*="blur-3xl"],[class*="blur-2xl"]{display:none!important;}
:focus-visible{outline:2px solid var(--ines-ink)!important;outline-offset:2px;}
::selection{background:var(--ines-red);color:#fff;}
img[data-mari-part="backdrop"][data-default-background]{opacity:0!important;}
.mari-app.geometric-grid,.mari-app.noise-bg{background-image:none!important;}

/* Buttons: rectangles. Primary = red slab. Everything else = ink hairline. */
.ov-btn{border:1px solid var(--ines-line)!important;background:transparent!important;color:var(--ines-ink)!important;font-weight:500;}
.ov-btn:hover{border-color:var(--ines-ink)!important;}
.ov-btn--primary,.ov-btn--accent{background:var(--ines-red)!important;border-color:var(--ines-red)!important;color:#fff!important;}
:is(input,textarea,select):not([type="range"]):not([type="checkbox"]):not([type="radio"]){border-color:var(--ines-line)!important;}
:is(input,textarea,select):focus{border-color:var(--ines-ink)!important;}
[class*="bg-[var(--primary)]/"]:not([data-settings-switch-track]),[class*="bg-primary/"]{background-color:var(--ov-active-bg)!important;}
/* switches: a hairline box; on = solid ink with a paper square */
[data-settings-switch-track]{background:var(--ines-paper)!important;border:1px solid var(--ines-ink)!important;padding:2px!important;}
[data-settings-switch-track] [data-settings-switch-thumb]{background:var(--ines-ink)!important;--tw-ring-color:transparent!important;width:14px!important;height:14px!important;}
[data-settings-switch-track][data-checked]{background:var(--ines-ink)!important;}
[data-settings-switch-track][data-checked] [data-settings-switch-thumb]{background:var(--ines-paper)!important;}
.ov-switch{background:var(--ines-paper)!important;border:1px solid var(--ines-ink);}
.ov-switch span{background:var(--ines-ink)!important;top:2px!important;left:2px!important;}
.ov-switch.is-on{background:var(--ines-ink)!important;}
.ov-switch.is-on span{background:var(--ines-paper)!important;}

/* ── TOP BAR ─────────────────────────────────────── */
/* the hairline is a border: a 1px gradient layer reads as a full ink plate to the guard (R4M1) */
[data-component="TopBar"]{border-bottom:1px solid var(--ines-ink)!important;}
[data-component="TopBar"] :is([aria-selected="true"],[aria-pressed="true"],.is-active),[data-component="TopBar"] .ov-tab.is-active{
  border-color:transparent!important;--tw-ring-color:transparent!important;outline:0;
  background:transparent!important;box-shadow:inset 0 -3px 0 var(--ines-red)!important;color:var(--ines-ink)!important;}
[data-component="TopBar"] :is(svg.lucide,.ov-tab){color:var(--ines-ink);}
[data-component="TopBar"] :is(.ov-mark,img){filter:grayscale(1) contrast(1.2);}
[data-component="TopBar"] :is(a,button,span){color:var(--ines-ink);}
[data-component="TopBar"] [class*="text-[var(--primary)]"],[data-component="TopBar"] [class*="accent"]{color:var(--ines-ink)!important;}

/* phone/tablet top bar */
.ovm-icon-btn.is-on{background:transparent!important;color:var(--ines-ink)!important;box-shadow:inset 0 -3px 0 var(--ines-red)!important;}
.ovm-stack-btn{color:var(--ines-ink)!important;}
.ovm-stack-btn.is-on{background:var(--ov-active-bg)!important;}

/* ── SIDEBARS ────────────────────────────────────── */
:is([data-component="ChatSidebar"],[data-component="TopBar"]) img:not([data-mari-part]){filter:grayscale(1) contrast(1.15);}
[data-component="ChatSidebar"] :is(select,[role="combobox"],button)[class*="primary"]{color:var(--ines-ink)!important;}
.ov-recent__text small{filter:grayscale(1);}
:is([data-component="ChatSidebar"],[data-component="RightPanelDesktop"],[data-component="RightPanelMobile"]){
  background:var(--ines-paper)!important;}
[data-component="ChatSidebar"]{border-right:1px solid var(--ines-ink)!important;}
[data-component="RightPanelDesktop"]{border-left:1px solid var(--ines-ink)!important;}
.mari-chrome-segmented__button{color:var(--ines-mute)!important;background:transparent!important;font-weight:500;}
.mari-chrome-segmented__button--selected{color:var(--ines-ink)!important;box-shadow:inset 0 -2px 0 var(--ines-ink)!important;background:transparent!important;}
.mari-chrome-segmented__button--selected *{color:var(--ines-ink)!important;}
:is([data-component="ChatSidebar"],[data-component="RightPanelDesktop"]) svg.lucide{color:var(--ines-mute);}
[data-chat-row]{min-height:48px;--tw-ring-color:transparent!important;}
[data-chat-row][data-selected="true"]{background:var(--ov-active-bg)!important;}
[data-chat-row] .mari-chrome-accent-progress{top:0!important;bottom:0!important;height:auto!important;width:3px!important;transform:none!important;translate:none!important;background:var(--ines-red)!important;}
[data-chat-row] .mari-chrome-text-strong{font-size:0.9375rem!important;font-weight:500!important;color:var(--ines-ink)!important;}
[data-chat-row] .mari-chrome-accent-text-muted{font-size:0.75rem!important;color:var(--ines-mute)!important;}
[data-chat-row] .h-7.w-7 > div:first-child{border:1px solid var(--ines-ink);background:var(--ines-paper)!important;color:var(--ines-ink)!important;font-size:0.75rem!important;}
[data-chat-row] .h-7.w-7 > span{width:7px!important;height:7px!important;right:-3px!important;bottom:-3px!important;--tw-ring-color:var(--ines-paper)!important;}
[data-chat-row] img{filter:grayscale(1) contrast(1.1);}
:root{--mari-chat-row-art-opacity:0;}
.mari-chrome-sort-field,.mari-chrome-sort-field option{color:var(--ines-ink)!important;}
.mari-chrome-field{font-size:0.8125rem!important;}

/* ── HOME ────────────────────────────────────────── */
[data-component="HomeBrowserHub.HomePage"]{background:transparent!important;}
:root[data-overhaul] .mari-home-hero{
  --ines-sun-h:136px;
  position:relative;align-items:flex-end!important;gap:16px 8px!important;
  min-height:232px;padding:32px calc(var(--ines-sun-h)*2 + 88px) 40px 0!important;margin-bottom:24px;
  border-bottom:12px solid var(--ines-ground);
  background:var(--ines-sun) right 24px bottom 0/auto var(--ines-sun-h) no-repeat;
}
.mari-home-browser-starfield,[class*="y2k-star"]{display:none!important;}
.ov-home-hero-actions{margin-left:0;}
:root[data-overhaul="on"] .ov-home-modes{margin-right:16px;}
.ov-home-hero-actions .ov-btn:not(#ines){border-color:transparent!important;background:transparent!important;padding:0!important;margin-right:16px;text-decoration:underline;text-decoration-thickness:1px;text-underline-offset:4px;font-weight:500!important;}
.ov-home-hero-actions .ov-btn:not(#ines):hover{text-decoration-thickness:2px;}
/* phone and narrow tablet: the sun gets its own strip under the buttons */
:root[data-overhaul="mobile"] .mari-home-hero{--ines-sun-h:76px;padding:24px 0 calc(var(--ines-sun-h) + 24px) 0!important;min-height:0;
  background:var(--ines-sun) right 16px bottom 0/auto var(--ines-sun-h) no-repeat!important;}
:root[data-overhaul="mobile"] .mari-home-hero h1{font-size:2.75rem!important;max-width:none;}
:root[data-overhaul="mobile"] .ov-home-modes{display:grid!important;grid-template-columns:repeat(3,minmax(0,1fr));width:100%;}
:root[data-overhaul="mobile"] .ov-home-modes > *{padding:0 8px!important;justify-content:center;}
:root[data-overhaul="mobile"] .ov-home-hero-actions{margin-left:0;}
@media (max-width:520px){ :root[data-overhaul="mobile"] .ov-home-modes svg{display:none!important;}
  :root[data-overhaul="mobile"] .ov-home-modes > * :is(span){font-size:0.8125rem!important;} :root[data-overhaul="mobile"] .ov-home-modes > *{padding:0 4px!important;} }
:root[data-overhaul] .mari-home-hero h1{
  font:700 clamp(2.5rem,4vw,3.5rem)/1.02 var(--ines-display)!important;letter-spacing:-0.035em!important;
  color:var(--ines-ink)!important;max-width:11em;}
:root[data-overhaul] .mari-home-hero > div:nth-child(2){flex:1 1 100%;flex-direction:column;align-items:flex-start!important;gap:12px!important;}
:root[data-overhaul] .mari-home-hero > div:nth-child(2) > div:first-child{order:0!important;}
:root[data-overhaul] .mari-home-hero > div:nth-child(2) > div:first-child > span{font-size:0.6875rem!important;font-weight:600!important;letter-spacing:0.14em!important;text-transform:uppercase;color:var(--ines-mute)!important;}
.ov-home-modes,.ov-home-hero-actions{gap:8px!important;}
.ov-home-modes > *,.ov-home-hero-actions .ov-btn{height:40px!important;border-radius:0!important;padding:0 16px!important;gap:8px!important;
  border:1px solid var(--ines-ink)!important;background:var(--ines-paper)!important;color:var(--ines-ink)!important;font-weight:600!important;font-size:0.875rem!important;}
.ov-home-modes > * span{font-size:0.875rem!important;font-weight:600!important;}
.ov-home-modes > *:first-child:not(#ines){background:var(--ines-ink)!important;color:var(--ines-paper)!important;}
.ov-home-modes > *:first-child:not(#ines) *{color:var(--ines-paper)!important;}
.ov-home-modes > * > span:first-child{border:0!important;background:transparent!important;width:auto!important;}
.ov-home-modes > * :is(span,svg){color:inherit!important;}
.ov-home-modes img{display:none!important;}
.mari-home-feed-grid{gap:16px!important;}
[data-mari-part="home-widget"]{
  border:1px solid var(--ines-line)!important;border-top:3px solid var(--ines-ink)!important;
  background:var(--ines-paper)!important;padding:20px 24px 24px!important;}
.mari-home-widget::before{display:none!important;}
.mari-home-widget{--mari-home-widget-hover-transform:none;--mari-home-widget-hover-filter:none;}
[data-mari-part="home-widget-eyebrow"]{color:var(--ines-mute)!important;letter-spacing:0.14em!important;font-weight:600!important;}
[data-mari-part="home-widget-title"],:root[data-overhaul] .mari-home-feed-grid :is(h2,h3){
  font-family:var(--ines-display)!important;font-weight:700!important;letter-spacing:-0.02em!important;color:var(--ines-ink)!important;}
[data-mari-part="home-widget-text"]{line-height:1.5!important;}
[data-mari-part="home-widget-title"]{line-height:1.12!important;}
/* shortcut sizes: v1.4 tokens (R4M4 fixed) */
.mari-home-widget-shortcut__title{font-weight:600!important;}
.mari-home-widget-shortcut__description{color:var(--ines-mute)!important;}
.mari-home-widget-shortcut{gap:12px!important;}
.mari-home-widget-shortcut-list{gap:6px!important;}
[data-mari-part="home-widget"] img{filter:grayscale(1) contrast(1.1);}
.mari-home-widget .mari-chrome-accent-icon{color:var(--ines-ink)!important;}
.mari-home-widget [class*="uppercase"]{color:var(--ines-mute)!important;}
/* recent chats: a list with rules, square letter marks */
.ov-recent button{border-radius:0!important;padding:8px 0!important;border-bottom:1px solid var(--ines-line)!important;}
.ov-recent li:last-child button{border-bottom:0!important;}
.ov-recent__avatar{border-radius:0!important;background:transparent!important;border:1px solid var(--ines-ink)!important;color:var(--ines-ink)!important;font-weight:600;}
.ov-recent__text strong{font-size:0.9375rem!important;}
.ov-recent__text small{font-size:0.875rem!important;}
.ov-recent__mode{border:0!important;padding:0!important;text-transform:uppercase;letter-spacing:0.12em;font-size:0.6875rem!important;font-weight:600;color:var(--ines-mute)!important;}
.ov-recent__time{font-size:0.8125rem!important;color:var(--ines-mute)!important;font-variant-numeric:tabular-nums;}
/* the one poster on a card: What's new */
.mari-home-widget--whats-new [data-mari-part="home-widget"]{background:var(--ines-paper) url("theme:poster-card.png") right 24px top 24px/auto min(calc(100% - 48px),160px) no-repeat!important;}
:root:not([data-theme="light"]) .mari-home-widget--whats-new [data-mari-part="home-widget"]{background-image:url("theme:poster-card-night.png")!important;}
.mari-home-widget--whats-new header{padding-right:184px!important;}
.mari-home-widget--whats-new :is(p,a,button){font-size:0.875rem!important;}

/* ── CHAT ────────────────────────────────────────── */
[data-chat-mode]{background-image:none!important;}
[data-mari-part="message"] :is(.mari-rp-bubble,.mari-message-bubble){background:transparent!important;border:0!important;}
[data-mari-part="message"] *{-webkit-text-stroke:0!important;}
/* avatars: a square tile, hairline frame, no ring, no glow */
[data-mari-part="message"] [data-mari-part="avatar"] > :is(div,button){border:1px solid var(--ines-line-strong)!important;background:var(--ines-paper)!important;
  --tw-ring-color:transparent!important;--tw-ring-shadow:0 0 #0000!important;background-image:none!important;color:var(--ines-ink)!important;}
[data-mari-part="message"] [data-mari-part="avatar"] img{filter:grayscale(1) contrast(1.1);}
[data-mari-part="message"] [data-mari-part="avatar"] *{color:var(--ines-ink)!important;}
[data-mari-part="message"][data-character="captain-ilsa-varn"] [data-mari-part="avatar"] > :is(div,button){background:var(--ines-paper) radial-gradient(circle,var(--ines-red) 0 33%,transparent 34%)!important;}
[data-mari-part="message"][data-character="captain-ilsa-varn"] [data-mari-part="avatar"] > :is(div,button) > *{opacity:0;}
/* name line: name 15px semibold, time 13px grey, a pictogram per role */
[data-mari-part="message"] [data-mari-part="header"]{align-items:center;}
/* v6: the avatar tile's top edge sits on the turn rule */
@media (min-width:768px){[data-mari-part="message"]:not([data-vn]) [data-mari-part="avatar"]{margin-top:-4px;}}
[data-mari-part="message"] .mari-message-name{font-size:0.9375rem!important;font-weight:600!important;letter-spacing:-0.005em!important;color:var(--ines-ink)!important;}
