/* ── LONG REPLIES: v1.5 tokens ────────────────────── */
/* one measure: 36em, about 65 characters of Inter. Messages and the message box share one column. */
:root{
  --ines-measure:36em;
  --mari-message-measure:36em;
  --mari-chat-column:36rem;             /* = the measure: text, rules and message box share both edges; avatars hang in the margin */
  --mari-chat-line-height:1.55;
  --mari-paragraph-gap:0.9em;
  --mari-dialogue-weight:600;           /* **"..."** is medium, not a black slab */
  --mari-pinned-speaker:on;             /* the name line stays while you read a tall reply */
  --mari-pinned-speaker-bg:var(--ines-paper);
  --mari-pinned-speaker-bleed:0px;
  --mari-phone-avatar:hidden;
  --mari-message-actions:var(--ines-mute);
  --mari-swipe-counter:var(--ines-mute);
  --mari-vn-fade:1.5rem;
}
:root:not([data-theme="light"]){--mari-dialogue-weight:560;}
.mari-message-content{hanging-punctuation:first;}
.mari-message-content :is(strong,b){font-weight:var(--mari-dialogue-weight)!important;color:var(--mari-dialogue-color)!important;}
.mari-message-content em{font-style:italic;color:inherit;}
/* the --- scene break: one short 3px bar on the grid, not a window-wide hairline */
.mari-message-content hr.mari-md-rule{border:0!important;height:3px!important;width:48px!important;background:var(--ines-ink)!important;margin:1.6em 0!important;opacity:1!important;}
/* lists: hanging numerals in tabular figures */
.mari-message-content :is(ol,ul){padding-left:1.6em!important;margin:0.4em 0 0!important;}
.mari-message-content li{padding-left:0.2em;margin:0.25em 0!important;}
.mari-message-content li::marker{font-weight:600;font-variant-numeric:tabular-nums;color:var(--ines-ink);}
.mari-message-content ul li::marker{content:"— ";font-weight:400;}
/* one pictogram per speaker: the avatar tile carries it, so the head loses its dot on desktop */
[data-mari-part="message"]:not([data-vn]) [data-mari-part="avatar"] ~ * [data-mari-part="header"]::before,
[data-mari-part="message"]:has([data-mari-part="avatar"]) [data-mari-part="header"]::before{display:none!important;}
[data-mari-part="message"] [data-mari-part="avatar"] > [data-mari-part="avatar-placeholder"]{background:var(--ines-paper)!important;border:1px solid var(--ines-ink)!important;color:transparent!important;}
[data-mari-part="avatar-placeholder"] > *,[data-mari-part="avatar"] > button:has(> div > svg.lucide-user) > div > svg{opacity:0!important;}
[data-mari-part="message"] [data-mari-part="avatar"] > [data-mari-part="avatar-placeholder"][data-role="user"],
[data-mari-part="message"] [data-mari-part="avatar"] > button:has(> div > svg.lucide-user){background:linear-gradient(var(--ines-ink),var(--ines-ink)) center/34% 34% no-repeat,var(--ines-paper)!important;border:1px solid var(--ines-ink)!important;}
[data-mari-part="message"] [data-mari-part="avatar"] > [data-mari-part="avatar-placeholder"][data-role="assistant"]{background:radial-gradient(circle,var(--ines-ink) 0 17%,transparent 18%),var(--ines-paper)!important;}
[data-mari-part="message"][data-character="captain-ilsa-varn"] [data-mari-part="avatar"] > [data-mari-part="avatar-placeholder"]{background:radial-gradient(circle,var(--ines-red) 0 33%,transparent 34%),var(--ines-paper)!important;}
/* message tools: quiet but legible */
[data-mari-part="actions"] :is(button,svg){color:var(--ines-mute)!important;opacity:1!important;}
[data-mari-part="actions"] button:hover :is(svg){color:var(--ines-ink)!important;}
/* composer: the persona chip is a square letter, ink on paper; the box lines up with the reading column */
[data-mari-part="composer"] button[class*="rounded-full"][class*="h-8"]{border-color:transparent!important;}
/* v6: the persona chip is your pictogram (the ink square), not a letter */
[data-mari-part="composer"] button[class*="rounded-full"][class*="h-8"] > div[class*="bg-foreground/10"],
[data-mari-part="composer"] [data-mari-part="avatar-placeholder"]{background:linear-gradient(var(--ines-ink),var(--ines-ink)) center/10px 10px no-repeat,var(--ines-paper)!important;border:1px solid var(--ines-ink)!important;color:transparent!important;}
[data-mari-part="composer"] [data-mari-part="avatar-placeholder"] > *{opacity:0!important;}
/* phone: no avatar column (also --mari-phone-avatar:hidden). Text runs on a symmetric 16px gutter; the head keeps the pictogram. */
@media (max-width:640px){
  [data-mari-part="message"]:not([data-vn]) [data-mari-part="avatar"]{display:none!important;}
  [data-mari-part="message"]:not([data-vn]):not(#ines) [data-mari-part="header"]::before{display:inline-block!important;align-self:center;}
  [data-mari-part="message"]:not([data-vn]) [data-mari-part="header"][data-placement="outside"]{padding-left:0!important;padding-right:0!important;}
  [data-mari-part="message"]:not([data-vn]) .mari-rp-bubble{max-width:none;}
  [data-mari-part="message"]:not([data-vn]) .mari-message-body{max-width:none!important;flex:1 1 auto!important;width:100%;}
  [data-mari-part="message"]:not([data-vn]).mari-roleplay-message-row{padding-left:11px!important;padding-right:11px!important;}
}

/* Library cards with no picture: a printed pictogram on paper, never a grey gradient with a stock icon */
.ov-card__art:has(> .ov-card__ph){background:var(--ines-paper)!important;border:1px solid var(--ines-line)!important;
  background-image:radial-gradient(circle,var(--ines-ink) 0 15%,transparent 15.5%)!important;}
.ov-card:nth-child(3n+2) .ov-card__art:has(> .ov-card__ph){background-image:linear-gradient(var(--ines-ink),var(--ines-ink))!important;background-size:28% 22%!important;background-position:center!important;background-repeat:no-repeat!important;}
.ov-card:nth-child(3n+3) .ov-card__art:has(> .ov-card__ph){background-image:linear-gradient(var(--ines-ink),var(--ines-ink))!important;background-size:46% 6px!important;background-position:center!important;background-repeat:no-repeat!important;}
.ov-card__art:has(> .ov-card__ph):hover{border-color:var(--ines-ink)!important;}
.ov-card__ph{opacity:0!important;}

@media (max-width:520px){ .ov-recent__mode{display:none!important;} }
/* name above the card (phones, tablets): the opening rule goes above the name, so the head reads the same everywhere */
[data-mari-part="message"]:not([data-vn]):has(> * > [data-mari-part="header"][data-placement="outside"]) .mari-rp-bubble,
[data-mari-part="message"]:not([data-vn]):has([data-mari-part="header"][data-placement="outside"]) .mari-rp-bubble{border-top:0!important;}
[data-mari-part="message"]:not([data-vn]) [data-mari-part="header"][data-placement="outside"]{border-top:1px solid var(--ines-line);padding-top:10px;}
[data-mari-part="message"][data-latest]:not([data-vn]) [data-mari-part="header"][data-placement="outside"]{border-top:3px solid var(--ines-ink);}

/* the chrome accent is flat ink everywhere, gradients included */
:root{--mari-chrome-accent-gradient:linear-gradient(var(--mari-chrome-accent),var(--mari-chrome-accent));}

/* ── VN (v6): the dialogue box is a panel like the others: ink hairline, 3px opening rule ── */
.mari-chat-style-surface:has(> [data-mari-part="message"][data-vn]){border:1px solid var(--ines-ink)!important;border-top-width:3px!important;background:var(--ines-paper)!important;}
[data-mari-part="message"][data-vn] [data-mari-part="header"]{color:var(--ines-ink)!important;font-size:0.9375rem!important;font-weight:600!important;letter-spacing:-0.005em;}
[data-mari-part="message"][data-vn] .mari-message-content{line-height:1.55!important;}
[data-mari-part="vn-nav"]{color:var(--ines-ink)!important;background:transparent!important;font-size:0.875rem!important;font-weight:500;}
@media (hover:hover){[data-mari-part="vn-nav"]:hover{text-decoration:underline;text-decoration-thickness:1px;text-underline-offset:4px;}}
[data-mari-part="vn-nav"]:disabled{color:var(--ines-faint)!important;opacity:1!important;}
[data-mari-part="vn-counter"]{color:var(--ines-mute)!important;opacity:1!important;font-size:0.8125rem!important;font-variant-numeric:tabular-nums;letter-spacing:0.04em;}
[data-mari-part="message"][data-vn] [data-mari-part="header"] > span:not(#ines){color:var(--ines-ink)!important;font-size:0.9375rem!important;font-weight:600!important;}
[data-mari-part="vn-nav"],[data-mari-part="vn-counter"]{white-space:nowrap;}
@media (max-width:640px){
  /* phone: the VN box takes the message box's edges; the buttons keep one line */
  .mari-chat-style-surface:has(> [data-mari-part="message"][data-vn]){margin-inline:7px;}
  [data-mari-part="vn-nav"]{font-size:0.8125rem!important;padding-inline:4px!important;}
}
@media (max-width:640px){
  /* phone VN: the portrait tile shrinks to the 40px grid unit so the line keeps about 30 characters */
  [data-mari-part="message"][data-vn] [data-mari-part="avatar"]{width:40px!important;height:40px!important;min-width:40px!important;flex:none!important;}
  [data-mari-part="message"][data-vn] [data-mari-part="avatar"] > *{width:40px!important;height:40px!important;}
}

/* ── Ctrl+K (v6): one red per screen. Choices and tabs are ink; the field has one frame, not two ── */
[data-component="GlobalOmnibar.Panel"] input{outline:0!important;}
[data-component="GlobalOmnibar.Panel"] :is(button[aria-pressed="true"],button[aria-selected="true"],[role="radio"][aria-checked="true"]){background:var(--ines-ink)!important;color:var(--ines-paper)!important;border-color:var(--ines-ink)!important;}
[data-component="GlobalOmnibar.Panel"] :is(button[aria-pressed="true"],button[aria-selected="true"],[role="radio"][aria-checked="true"]) *{color:var(--ines-paper)!important;}
[data-component="GlobalOmnibar.Panel"] input[type="checkbox"] + span{background:var(--ines-paper)!important;border:1px solid var(--ines-ink)!important;}
[data-component="GlobalOmnibar.Panel"] input[type="checkbox"]:checked + span{background:var(--ines-ink)!important;}
[data-component="GlobalOmnibar.Panel"] input[type="checkbox"] + span > span{background:var(--ines-ink)!important;}
[data-component="GlobalOmnibar.Panel"] input[type="checkbox"]:checked + span > span{background:var(--ines-paper)!important;}
[data-component="GlobalOmnibar.Panel"] :is(mark,[class*="text-[var(--primary)]"]){background:transparent!important;color:var(--ines-ink)!important;font-weight:700;text-decoration:underline;text-decoration-thickness:1px;text-underline-offset:3px;}

/* editor with no picture (v6): the printed disc, not a stock person glyph */
.ov-rail__portrait.is-empty .ov-rail__portrait-empty{background:radial-gradient(circle at 50% calc(50% - 40px),var(--ines-ink) 0 24px,transparent 24.5px)!important;}
.ov-rail__portrait.is-empty .ov-rail__portrait-empty svg{height:24px!important;}
.ov-rail__portrait.is-empty .ov-rail__portrait-empty svg{opacity:0!important;}
.ov-rail__portrait.is-empty .ov-rail__portrait-empty span{color:var(--ines-mute)!important;font-size:0.8125rem!important;}

/* v6: names above the card (phones, tablets): your head reads left to right like everyone else's, and its rule spans the column */
[data-mari-part="message"]:not([data-vn]) [data-mari-part="header"][data-placement="outside"]{flex-direction:row!important;justify-content:flex-start!important;width:100%;padding-left:0!important;padding-right:0!important;}
