@media (min-width:641px) and (max-width:1023px){
  [data-mari-part="composer"][data-composer="roleplay"] > .mari-chat-input-box{margin-inline:36px!important;}
}

/* v6.1: What's new keeps its poster at every width; its two-line title gets the room it needs (1920 overlap) */
.mari-home-widget--whats-new header,.mari-home-widget--whats-new header > div{height:auto!important;max-height:none!important;min-height:0!important;}
